/**
 * Canonical permission keys.
 *
 * GENERATED by scripts/generateRbac.js from matrix.json — do not edit by hand.
 * Run `npm run rbac:generate` after changing the matrix.
 *
 * These constants exist for typo-safety at call sites. They are NOT an
 * authority on what a user may do — the caller's real permission set comes
 * from the database via `get_my_permissions()`, and the security boundary is
 * RLS (`auth_has_permission`). Client gating is UX only.
 */

