export type Permission = (typeof PERMISSIONS)[keyof typeof PERMISSIONS];

/** Every permission key, for iteration and validation. */
export const ALL_PERMISSIONS: readonly Permission[] = Object.values(PERMISSIONS);

/**
 * Tab id -> the permission required to see it.
 *
 * Consumed by the bottom tab bar and the More menu. Both must fail CLOSED:
 * a tab id missing from this map is hidden, never shown.
 */
export const TAB_PERMISSION: Record<string, Permission> = {
  Home: PERMISSIONS.HOME_VIEW,
  Rooms: PERMISSIONS.ROOMS_VIEW,
  Chat: PERMISSIONS.CHAT_VIEW,
  Tickets: PERMISSIONS.TICKETS_VIEW,
  LostAndFound: PERMISSIONS.LOST_AND_FOUND_VIEW,
  Staff: PERMISSIONS.STAFF_VIEW,
  Settings: PERMISSIONS.SETTINGS_VIEW,
};

/**
 * Tab order used to resolve a landing route. The first tab whose permission
 * the user holds is where the app opens — so F&B/Kitchen staff, who have no
 * Dashboard right, land on Tickets rather than a screen they cannot see.
 */
export const TAB_ORDER: readonly string[] = [
  'Home',
  'Rooms',
  'Chat',
  'Tickets',
  'LostAndFound',
  'Staff',
  'Settings',
];
